-- Original Muse dream-symbol editorial starter library. No HeartYearning text copied.
select public.import_whimsy_content('[{"id":"dream-dog","version":1,"experience":"dreamscapes","category":"Animals","state":"published","title":"Dog","body":"A familiar animal that can feel like company, protection, or an untamed part of a relationship.","metadata":{"associations":"Companionship and trust | Loyalty that feels comforting or demanding | Instinct and protection","context":"Notice whether the dog followed, guarded, played, or frightened you; its behavior changes the tone.","question":"What kind of closeness did the dog seem to offer or ask for?","source":"Muse original editorial library"},"tags":["puppy","canine"],"sources":[]},{"id":"dream-bird","version":1,"experience":"dreamscapes","category":"Animals","state":"published","title":"Bird","body":"A creature moving between ground and sky, often noticed for its distance, song, or sudden arrival.","metadata":{"associations":"Freedom and perspective | Messages you hope to hear | Fragility and change","context":"A caged bird differs from one crossing open sky; notice the space around it.","question":"Where did you feel free or confined in this scene?","source":"Muse original editorial library"},"tags":["flying bird","wings"],"sources":[]},{"id":"dream-snake","version":1,"experience":"dreamscapes","category":"Animals","state":"published","title":"Snake","body":"An animal that may evoke both fear and fascination, especially when it sheds skin or appears unexpectedly.","metadata":{"associations":"Change and renewal | A boundary needing attention | Hidden knowledge or uncertainty","context":"Your own response matters more than a fixed cultural meaning; consider whether the snake threatened, watched, or transformed.","question":"What changed when you noticed the snake?","source":"Muse original editorial library"},"tags":["serpent"],"sources":[]},{"id":"dream-forest","version":1,"experience":"dreamscapes","category":"Nature and Elements","state":"published","title":"Forest","body":"A landscape with paths, cover, and places that cannot be seen all at once.","metadata":{"associations":"Exploration without a map | Shelter or concealment | The complexity of an inner question","context":"A sunlit path and a dark thicket invite different feelings; remember whether you were lost or choosing a route.","question":"What did the forest make possible, and what did it hide?","source":"Muse original editorial library"},"tags":["woods","trees"],"sources":[]},{"id":"dream-mountain","version":1,"experience":"dreamscapes","category":"Nature and Elements","state":"published","title":"Mountain","body":"A high place that can suggest a long climb, a clear view, or distance from everyday life.","metadata":{"associations":"Effort toward a goal | Perspective earned slowly | A challenge that feels larger than you","context":"Were you climbing, resting, watching from below, or already at the summit?","question":"What did the height change about how you saw things?","source":"Muse original editorial library"},"tags":["peak","hill"],"sources":[]},{"id":"dream-storm","version":1,"experience":"dreamscapes","category":"Nature and Elements","state":"published","title":"Storm","body":"Weather that interrupts plans and changes the atmosphere quickly.","metadata":{"associations":"Strong emotion | A disruption outside your control | Energy waiting for release","context":"Sheltering, dancing, or being swept away describe very different relationships to the storm.","question":"What were you trying to protect or release during the storm?","source":"Muse original editorial library"},"tags":["thunder","lightning"],"sources":[]},{"id":"dream-ocean","version":1,"experience":"dreamscapes","category":"Water","state":"published","title":"Ocean","body":"A vast moving surface that can feel peaceful, unknowable, or overwhelming.","metadata":{"associations":"Emotional depth | Open possibility | Uncertainty without clear edges","context":"Notice whether the water was calm, rough, inviting, or distant, and whether you were on shore or inside it.","question":"How close did you want to be to the water?","source":"Muse original editorial library"},"tags":["sea","waves"],"sources":[]},{"id":"dream-river","version":1,"experience":"dreamscapes","category":"Water","state":"published","title":"River","body":"Water moving through a landscape, sometimes gently and sometimes faster than expected.","metadata":{"associations":"A life transition | Being carried by events | A route through complexity","context":"Crossing a river differs from drifting along it; look at your direction and sense of choice.","question":"Were you following the current or finding your own crossing?","source":"Muse original editorial library"},"tags":["stream","current"],"sources":[]},{"id":"dream-flood","version":1,"experience":"dreamscapes","category":"Water","state":"published","title":"Flood","body":"Water entering places normally kept dry, often with a sudden change in scale.","metadata":{"associations":"Too much arriving at once | A need to adapt | Old boundaries becoming porous","context":"The dream may reflect intensity without predicting danger; recall what, if anything, stayed safe.","question":"What felt submerged, and what remained within reach?","source":"Muse original editorial library"},"tags":["rising water","overflow"],"sources":[]},{"id":"dream-stranger","version":1,"experience":"dreamscapes","category":"People and Relationships","state":"published","title":"Stranger","body":"An unfamiliar person who may feel like a new possibility, a threat, or a part of the scene you have not named.","metadata":{"associations":"Unfamiliar aspects of yourself | A change in trust | Curiosity about someone new","context":"Pay attention to their actions rather than assuming every stranger stands for one thing.","question":"What did this person know or do that surprised you?","source":"Muse original editorial library"},"tags":["unknown person","unfamiliar face"],"sources":[]},{"id":"dream-childhood-friend","version":1,"experience":"dreamscapes","category":"People and Relationships","state":"published","title":"Childhood Friend","body":"Someone connected with an earlier version of your life, whether or not you still know them now.","metadata":{"associations":"Memory and continuity | A quality you once shared | An unfinished conversation","context":"The dream may be about a time in your life rather than the person themselves.","question":"What part of your younger self did their presence bring back?","source":"Muse original editorial library"},"tags":["old friend","school friend"],"sources":[]},{"id":"dream-family-member","version":1,"experience":"dreamscapes","category":"People and Relationships","state":"published","title":"Family Member","body":"A familiar relationship carrying its own history, affection, tension, and expectations.","metadata":{"associations":"Belonging and distance | Care or obligation | A remembered family pattern","context":"Consider the actual relationship and the dream interaction before reaching for general symbolism.","question":"How did this meeting differ from waking life?","source":"Muse original editorial library"},"tags":["parent","sibling","relative"],"sources":[]},{"id":"dream-house","version":1,"experience":"dreamscapes","category":"Places and Buildings","state":"published","title":"House","body":"An interior with rooms, thresholds, and private spaces that may feel familiar or newly discovered.","metadata":{"associations":"Safety and belonging | An aspect of your personal life | Parts of a story not yet explored","context":"Which room mattered, and did the house feel like yours, someone else''s, or neither?","question":"What did you find behind the door you opened?","source":"Muse original editorial library"},"tags":["home","rooms"],"sources":[]},{"id":"dream-school","version":1,"experience":"dreamscapes","category":"Places and Buildings","state":"published","title":"School","body":"A place of learning and evaluation that may return long after formal school ends.","metadata":{"associations":"Learning something new | Old expectations | Feeling observed or tested","context":"Notice whether you were teaching, studying, wandering, or trying to find a class.","question":"What did you feel expected to know?","source":"Muse original editorial library"},"tags":["classroom","campus"],"sources":[]},{"id":"dream-bridge","version":1,"experience":"dreamscapes","category":"Places and Buildings","state":"published","title":"Bridge","body":"A structure between two places, sometimes sturdy and sometimes uncertain.","metadata":{"associations":"Transition and connection | Taking a step between roles | Trust in a path","context":"Was the bridge complete, crowded, narrow, or easy to cross?","question":"What was on each side, and which direction mattered?","source":"Muse original editorial library"},"tags":["crossing","overpass"],"sources":[]},{"id":"dream-key","version":1,"experience":"dreamscapes","category":"Objects","state":"published","title":"Key","body":"A small object that can open something, be lost, or fail to fit.","metadata":{"associations":"Access and choice | A solution that requires timing | Responsibility for a threshold","context":"A key only matters in relation to its lock and the person holding it.","question":"What were you hoping the key would open?","source":"Muse original editorial library"},"tags":["keys","lock"],"sources":[]},{"id":"dream-mirror","version":1,"experience":"dreamscapes","category":"Objects","state":"published","title":"Mirror","body":"A reflective surface that may show yourself, someone else, or an unexpected version of the scene.","metadata":{"associations":"Self-perception | A change in identity | Seeing something differently","context":"A distorted reflection may speak to uncertainty, not to a hidden truth about you.","question":"What felt familiar or unfamiliar in what you saw?","source":"Muse original editorial library"},"tags":["reflection","looking glass"],"sources":[]},{"id":"dream-phone","version":1,"experience":"dreamscapes","category":"Objects","state":"published","title":"Phone","body":"A tool for contact, missed calls, or messages that do not quite arrive.","metadata":{"associations":"Connection and reachability | An unanswered question | Information you want or avoid","context":"Did the device work, ring, disappear, or connect you with a specific person?","question":"Who were you trying to reach, and why then?","source":"Muse original editorial library"},"tags":["telephone","message"],"sources":[]},{"id":"dream-train","version":1,"experience":"dreamscapes","category":"Transportation","state":"published","title":"Train","body":"A journey on a shared route with stops, schedules, and other passengers.","metadata":{"associations":"Momentum and timing | A path shaped with others | An arrival or departure","context":"Missing a train differs from enjoying the ride; notice your sense of agency.","question":"Did you want to board, leave, or change direction?","source":"Muse original editorial library"},"tags":["railway","station"],"sources":[]},{"id":"dream-car","version":1,"experience":"dreamscapes","category":"Transportation","state":"published","title":"Car","body":"A familiar vehicle that makes the driver''s role and the road ahead especially noticeable.","metadata":{"associations":"Agency and control | Direction in a decision | Dependence on another driver","context":"Who was at the wheel, and could you see the road clearly?","question":"How did you feel about the route you were taking?","source":"Muse original editorial library"},"tags":["driving","vehicle"],"sources":[]},{"id":"dream-airplane","version":1,"experience":"dreamscapes","category":"Transportation","state":"published","title":"Airplane","body":"A long-distance journey that can hold excitement, fear, separation, or a wider view.","metadata":{"associations":"A leap in scale | Distance from the familiar | Plans with many moving parts","context":"Boarding, turbulence, and landing are different moments; recall which one carried the dream.","question":"Where were you going, and did you choose the destination?","source":"Muse original editorial library"},"tags":["flight","airport"],"sources":[]},{"id":"dream-teeth","version":1,"experience":"dreamscapes","category":"Body and Health","state":"published","title":"Teeth","body":"Teeth can appear in vivid dreams about speaking, appearance, physical sensation, or change.","metadata":{"associations":"Vulnerability and self-image | A difficulty saying something | A bodily sensation carried into sleep","context":"This image is common and is not a diagnosis; notice your actual feeling and any physical context.","question":"What mattered more: the sensation, the appearance, or who saw it?","source":"Muse original editorial library"},"tags":["tooth","mouth"],"sources":[]},{"id":"dream-hands","version":1,"experience":"dreamscapes","category":"Body and Health","state":"published","title":"Hands","body":"Hands make, hold, touch, and let go; their condition often shapes what is possible in a dream.","metadata":{"associations":"Capability and care | A need for contact | What you can or cannot hold","context":"Were your hands busy, injured, transformed, or unexpectedly gentle?","question":"What were you trying to make, carry, or release?","source":"Muse original editorial library"},"tags":["fingers","palms"],"sources":[]},{"id":"dream-voice","version":1,"experience":"dreamscapes","category":"Body and Health","state":"published","title":"Voice","body":"A voice may be loud, absent, musical, or difficult to use.","metadata":{"associations":"Expression and being heard | A message you are forming | Silence chosen or imposed","context":"Not being able to speak is different from deciding not to; consider who was listening.","question":"What did you most want to say?","source":"Muse original editorial library"},"tags":["speaking","singing","silence"],"sources":[]},{"id":"dream-laughter","version":1,"experience":"dreamscapes","category":"Emotions","state":"published","title":"Laughter","body":"Shared or solitary laughter that may feel joyful, nervous, or out of place.","metadata":{"associations":"Relief and play | Connection with others | A way to soften tension","context":"Were people laughing with you, at you, or because something absurd happened?","question":"What changed when the laughter began?","source":"Muse original editorial library"},"tags":["laughing","giggle"],"sources":[]},{"id":"dream-crying","version":1,"experience":"dreamscapes","category":"Emotions","state":"published","title":"Crying","body":"Tears in dreams can accompany grief, relief, frustration, or a release of feeling.","metadata":{"associations":"An emotion finding room | A need for comfort | Relief after holding something in","context":"The feeling around the tears matters more than the tears alone.","question":"What did the crying allow you to notice?","source":"Muse original editorial library"},"tags":["tears","weeping"],"sources":[]},{"id":"dream-fear","version":1,"experience":"dreamscapes","category":"Emotions","state":"published","title":"Fear","body":"A felt sense of alarm that can attach to many different dream scenes.","metadata":{"associations":"A perceived boundary | Uncertainty asking for care | A memory of vulnerability","context":"Dream fear is not proof of real danger; notice what the dream presented and what helped.","question":"What did you need in that moment?","source":"Muse original editorial library"},"tags":["scared","frightened"],"sources":[]},{"id":"dream-falling","version":1,"experience":"dreamscapes","category":"Actions and Events","state":"published","title":"Falling","body":"A sudden change in height that may end abruptly or transform into another movement.","metadata":{"associations":"Loss of footing | An unexpected transition | Letting go of control","context":"The landing, if any, and the feeling before the fall change its meaning.","question":"What happened just before you lost your footing?","source":"Muse original editorial library"},"tags":["fall","drop"],"sources":[]},{"id":"dream-flying","version":1,"experience":"dreamscapes","category":"Actions and Events","state":"published","title":"Flying","body":"Moving through the air without ordinary limits, sometimes freely and sometimes with effort.","metadata":{"associations":"Freedom and possibility | Distance from a problem | A new vantage point","context":"Could you steer, and was the flight joyful, exhausting, or frightening?","question":"What became visible from above?","source":"Muse original editorial library"},"tags":["float","soar"],"sources":[]},{"id":"dream-running","version":1,"experience":"dreamscapes","category":"Actions and Events","state":"published","title":"Running","body":"Fast movement that may be toward something, away from it, or simply for the pleasure of motion.","metadata":{"associations":"Urgency and pursuit | An effort to keep pace | Energy seeking direction","context":"Being chased, racing, and running freely are not the same scene.","question":"What were you moving toward or away from?","source":"Muse original editorial library"},"tags":["chase","race"],"sources":[]},{"id":"dream-ghost","version":1,"experience":"dreamscapes","category":"Supernatural and Fantasy","state":"published","title":"Ghost","body":"A figure that seems present and absent at once, sometimes familiar and sometimes unknown.","metadata":{"associations":"Memory lingering | An unfinished story | A presence you cannot easily place","context":"Consider who or what the figure reminded you of rather than assuming a supernatural message.","question":"What did the ghost want, if anything?","source":"Muse original editorial library"},"tags":["spirit","apparition"],"sources":[]},{"id":"dream-portal","version":1,"experience":"dreamscapes","category":"Supernatural and Fantasy","state":"published","title":"Portal","body":"An opening into a different place or set of rules.","metadata":{"associations":"An invitation to change | Curiosity about an alternative | A threshold with uncertain stakes","context":"Did you enter, hesitate, or only watch someone else pass through?","question":"What made the other side appealing or alarming?","source":"Muse original editorial library"},"tags":["gateway","other world"],"sources":[]},{"id":"dream-magic","version":1,"experience":"dreamscapes","category":"Supernatural and Fantasy","state":"published","title":"Magic","body":"An impossible change that still feels natural inside the dream.","metadata":{"associations":"A wish for agency | Wonder in the ordinary | An unexpected way through a problem","context":"Notice whether you performed the magic, witnessed it, or resisted it.","question":"What became possible when ordinary rules changed?","source":"Muse original editorial library"},"tags":["spell","enchantment"],"sources":[]},{"id":"dream-being-late","version":1,"experience":"dreamscapes","category":"Common Dream Scenarios","state":"published","title":"Being Late","body":"A recurring kind of dream in which timing feels urgent and the destination keeps moving.","metadata":{"associations":"Pressure and expectation | Fear of disappointing someone | Competing demands","context":"The dream does not predict failure; consider what made arrival difficult.","question":"Whose timetable mattered in the dream?","source":"Muse original editorial library"},"tags":["missed deadline","late arrival"],"sources":[]},{"id":"dream-getting-lost","version":1,"experience":"dreamscapes","category":"Common Dream Scenarios","state":"published","title":"Getting Lost","body":"A route becomes unfamiliar, even if the place itself seems known.","metadata":{"associations":"Uncertainty in a transition | A search for orientation | A chance to notice a new path","context":"Were you alone, asking for help, or enjoying the detour?","question":"What would have helped you feel oriented?","source":"Muse original editorial library"},"tags":["lost","wrong turn"],"sources":[]},{"id":"dream-taking-an-exam","version":1,"experience":"dreamscapes","category":"Common Dream Scenarios","state":"published","title":"Taking an Exam","body":"A task with rules and judgment that may arrive without warning.","metadata":{"associations":"Evaluation and self-expectation | A skill you are learning | Fear of being found unready","context":"Many people dream of exams years later; the scene is not a measure of real ability.","question":"What did you believe was being measured?","source":"Muse original editorial library"},"tags":["test","unprepared"],"sources":[]}]'::jsonb);
